package com.paybridge.portpos;
import static com.github.tomakehurst.wiremock.client.WireMock.*;import static org.junit.jupiter.api.Assertions.*;import com.github.tomakehurst.wiremock.junit5.WireMockExtension;import com.paybridge.core.model.*;import java.net.URI;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.RegisterExtension;
class PortPosPaymentGatewayTest {@RegisterExtension static WireMockExtension wm=WireMockExtension.newInstance().options(com.github.tomakehurst.wiremock.core.WireMockConfiguration.wireMockConfig().dynamicPort()).build();@Test void creates_hosted_invoice(){wm.stubFor(post("/payment/v2/invoice").withHeader("Authorization",matching("Bearer .+")).willReturn(aResponse().withStatus(201).withHeader("Content-Type","application/json").withBody("{\"result\":\"success\",\"data\":{\"invoice_id\":\"INV1\",\"order\":{\"status\":\"PENDING\"},\"action\":{\"url\":\"https://payment.example/INV1\"}}}")));var p=gateway().createPayment(new PaymentRequest(Money.of("100","BDT"),"order-1","Book",null,new IdempotencyKey("order-1"),null,new Customer("A","a@example.com","01700000000",new BillingAddress("1 Road","Dhaka","Dhaka","1200","BD"))));assertEquals("INV1",p.reference().value());assertEquals(PaymentStatus.PENDING,p.status());assertEquals("https://payment.example/INV1",p.clientActionUrl());}@Test void starts_partial_refund(){wm.stubFor(post("/payment/v2/invoice/refund/INV1").withRequestBody(containing("refund")).willReturn(aResponse().withStatus(202).withHeader("Content-Type","application/json").withBody("{\"result\":\"SUCCESS\",\"data\":{\"order\":{\"status\":\"REFUND_PENDING\"}}}")));var r=gateway().refund(new RefundRequest(new PaymentReference(PaymentProvider.of("portpos"),"INV1"),Money.of("10","BDT"),new IdempotencyKey("refund-1")));assertEquals(Refund.Status.PENDING,r.status());}private PortPosPaymentGateway gateway(){return new PortPosPaymentGateway(new PortPosConfiguration("app","secret",URI.create(wm.baseUrl()),URI.create("https://merchant.example/return"),URI.create("https://merchant.example/ipn")));}}
